test('partial payment and authorized carry preserve 890 original goods and avoid double 90',()=>{const f=fixture();f.go({type:'close_group',group_id:f.g});const b=f.state.invoices[0];f.go({type:'receipt_confirm',customer_email:'customer@example.com',amount_twd:800,kind:'bank_confirmed',transaction_id:'bank-1',evidence:'bank statement',confirmed:true,allocations:[{invoice_id:b.id,amount_twd:800}]});assert.equal(balance(f.state,f.state.invoices[0]),90);f.go({type:'carry_to_second',order_id:f.o,amount_twd:90,confirmed:true,evidence:'authorized carry',included_in_second:false});f.go({type:'second_settle',order_id:f.o,costs:{domestic:38},confirmed:true,evidence:'shipping cost'});assert.equal(f.state.orders[0].goods_twd,890);assert.deepEqual(f.state.invoices.map(b=>b.amount_twd),[800,128]);assert.throws(()=>f.go({type:'carry_to_second',order_id:f.o,amount_twd:90,confirmed:true,evidence:'again',included_in_second:false}),/尾款|超過|確認/)});
