test('hold survives its date and purchase enforces real card budget and payment',()=>{const f=fixture();f.go({type:'close_group',group_id:f.g});let s=structuredClone(f.state);s.orders[0].items[0].hold={until:'2026-11-04',reason:'Ensky card limit'};const l=s.orders[0].items[0],c={type:'purchase_record',shop:'official',official_order:'P-1',currency:'JPY',original_amount:1000,actual_twd:0,evidence:'official proof',items:[{order_id:f.o,item_id:l.id,quantity:1}],advance_approved:true,advance_reason:'authorized'};assert.throws(()=>applyOperation(s,c,{id:'x',now:'2026-11-05T00:00:00Z'}),/解除/);s=applyOperation(s,{type:'hold_release',order_id:f.o,item_id:l.id,confirmed:true,evidence:'actual limit restored'},{id:'release'}).state;assert.throws(()=>applyOperation(s,{...c,actual_twd:300},{id:'x'}),/額度/);s=applyOperation(s,{type:'card_budget',available_twd:100,limit_twd:22000,confirmed:true,evidence:'bank card'},{id:'budget'}).state;assert.throws(()=>applyOperation(s,{...c,actual_twd:300},{id:'x'}),/超過/);assert.equal(applyOperation(s,c,{id:'purchase'}).state.orders[0].items[0].purchased,1)});
test('historic purchase backfill preserves the actual charge without debiting current credit or invoices',()=>{
 const f=fixture();f.go({type:'card_budget',available_twd:2467,limit_twd:22000,confirmed:true,evidence:'verified bank card'});
 const item={order_id:f.o,item_id:f.state.orders[0].items[0].id,quantity:1};
 const c={type:'purchase_record',shop:'historical official shop',official_order:'HISTORY-1',currency:'JPY',original_amount:5000,actual_twd:1387,evidence:'old official invoice and bank statement',items:[item],budget_mode:'historical',purchased_at:'2026-10-21',historical_reason:'2026-10-21 card transaction already reflected in current balance',historical_confirmed:true,advance_approved:true,advance_reason:'owner approved historical purchase before invoice'};
 assert.throws(()=>f.go({...c,historical_confirmed:false}),/補登原因/);
 assert.throws(()=>f.go({...c,historical_reason:''}),/補登原因/);
 assert.throws(()=>f.go({...c,purchased_at:'2026-11-05'}),/不晚於今日/);
 assert.throws(()=>f.go({...c,purchased_at:'2026-02-30'}),/不晚於今日/);
 assert.throws(()=>f.go({...c,budget_mode:'other'}),/處理方式無效/);
 const before=structuredClone(f.state.invoices),res=f.go(c),purchase=f.state.purchases[0];
 assert.equal(f.state.config.card_available_twd,2467);
 assert.equal(res.card_budget_impact_twd,0);assert.equal(purchase.card_budget_impact_twd,0);
 assert.equal(purchase.actual_twd,1387);assert.equal(purchase.budget_mode,'historical');assert.equal(purchase.purchased_at,'2026-10-21');
 assert.deepEqual(f.state.invoices,before);assert.equal(f.state.orders[0].items[0].purchased,1);
 assert.throws(()=>f.go({...c,official_order:'HISTORY-1'}),/官方訂單已登錄/);
});
