test('public checkout enters operating ledger and retry after closure preserves original order without duplicate',async()=>{const {checkoutOperations,publicOperationsCatalog}=await import('../operations-store.js');const env=dbEnv();await installOperations(env);const f=fixture();f.go({type:'group_save',id:f.g,title:'測試團次',status:'open',deadline:'2099-01-01T00:00:00Z',payment_due_at:'2099-01-02T00:00:00Z'});f.go({type:'product_save',group_id:f.g,name:'官方商品',sku:'OFF1',variant:'白色 M',price_twd:350,shipping_units:2,source_url:'https://official.example/item',image_url:'https://official.example/item.jpg',image_official:true,published:true,confirmed:true,quantity_limit:2});env.db.prepare("UPDATE pl_ops_state SET document_json=? WHERE id='main'").run(JSON.stringify(f.state));const p=f.state.products[0];const body={key:'checkout-test-00000001',name:'測試顧客',group_id:f.g,adult_confirmed:true,terms_confirmed:true,items:[{product_id:p.id,quantity:2}]};const r=await checkoutOperations(body,'buyer@example.com',env);let current=await loadOperations(env);const o=current.state.orders.find(o=>o.id===r.result.order_id);assert.equal(o.email,'buyer@example.com');assert.equal(o.goods_twd,700);assert.equal(o.acceptance.terms_confirmed,true);assert.equal(o.items[0].shipping_units,2);assert.equal(current.state.notices.length,0);await executeOperation({key:'close-next-0001',version:current.version,command:{type:'close_group',group_id:f.g}},'owner',env);assert.equal((await checkoutOperations(body,'buyer@example.com',env)).replayed,true);await assert.rejects(()=>checkoutOperations({...body,name:'changed'},'buyer@example.com',env),/識別碼/);current=await loadOperations(env);assert.equal(publicOperationsCatalog(current.state).products.length,0);await assert.rejects(()=>checkoutOperations({...body,key:'checkout-test-00000002'},'buyer@example.com',env),/截止/);assert.equal(current.state.orders.filter(o=>o.email==='buyer@example.com').length,1);assert.equal(current.state.invoices.find(b=>b.order_id===o.id).amount_twd,700);assert.ok(env.db.prepare("SELECT count(*) n FROM pl_ops_entity_history WHERE kind='products'").get().n>0);env.db.close()});
