test('full backup restores receipts, allocations, commands, attachment hashes and holds only into an empty target',async()=>{const{exportOperationsBackup,restoreOperationsBackup,verifyOperationsBackup}=await import('../operations-backup.js');const env=dbEnv();await installOperations(env);const f=fixture();f.go({type:'close_group',group_id:f.g});f.state.orders[0].items[0].hold={until:'2026-11-04',reason:'Ensky card'};env.db.prepare("UPDATE pl_ops_state SET document_json=? WHERE id='main'").run(JSON.stringify(f.state));await saveOperationsAttachment({name:'proof.pdf',mime_type:'application/pdf',base64_data:btoa('%PDF-1.4\ntest')},'owner',env);const n=f.state.notices[0];await executeOperation({key:'backup-approve-0001',version:0,command:{type:'notice_approve',notice_id:n.id,version:n.version,content:noticeContent(n),confirmed:true}},'owner',env);const file=await exportOperationsBackup(env);const target=dbEnv();await installOperations(target);await restoreOperationsBackup(file,'owner',target,{confirmed:true,expected_version:0});const restored=await loadOperations(target);assert.equal(restored.state.notices[0].status,'unknown');assert.equal(restored.state.orders[0].items[0].hold.reason,'Ensky card');assert.equal(target.db.prepare('SELECT COUNT(*) n FROM pl_ops_attachments').get().n,1);await assert.rejects(()=>restoreOperationsBackup(file,'owner',target,{confirmed:true,expected_version:restored.version}),/空白/);const broken=structuredClone(file);broken.payload.state.orders[0].goods_twd=1;await assert.rejects(()=>restoreOperationsBackup(broken,'owner',dbEnv(),{confirmed:true,expected_version:0}),/校驗/);const verified=await verifyOperationsBackup(env,'owner');assert.equal(verified.orders,1);assert.equal(verified.attachments,1);assert.equal(verified.delivery_replay_disabled,true);assert.equal(env.db.prepare("SELECT COUNT(*) n FROM sqlite_master WHERE name LIKE 'pl_ops_verify_%'").get().n,0);assert.equal((await loadOperations(env)).state.notices[0].status,'queued');env.db.close();target.db.close()});
test('operational mirror separates both destinations and only acknowledges exact events; conflicts never auto overwrite',async()=>{const{drainOperationsMirror,operationsMirrorStatus}=await import('../operations-mirror.js');const env=dbEnv();env.PL3_OPS_SYNC_ENABLED='true';env.PL3_FORMAL_SYNC_SECRET='local-test';env.PL3_FORMAL_SHEETS_WEBHOOK_URL='https://script.google.com/macros/s/test/exec';await installOperations(env);const f=fixture();f.go({type:'close_group',group_id:f.g});env.db.prepare("UPDATE pl_ops_state SET document_json=? WHERE id='main'").run(JSON.stringify(f.state));let sends=0;const ack=async(url,opt)=>{sends++;const envelope=JSON.parse(opt.body),v=JSON.parse(envelope.body);assert.match(envelope.signature,/^[a-f0-9]{64}$/);assert.equal(v.protocol,'pl3-operations-v1');return new Response(JSON.stringify({ok:true,ack_event_id:v.event_id,destination:v.destination,remote_id:v.record_id,remote_revision:'r1'}))};assert.equal((await drainOperationsMirror(env,{transport:ack})).handled,2);assert.equal((await operationsMirrorStatus(env)).delivered,2);assert.equal((await drainOperationsMirror(env,{transport:ack})).handled,0);assert.equal(sends,2);const current=await loadOperations(env);await executeOperation({key:'mirror-funds-0001',version:current.version,command:{type:'receipt_confirm',customer_email:'customer@example.com',amount_twd:890,kind:'bank_confirmed',transaction_id:'mirror-bank',evidence:'bank statement',confirmed:true,allocations:[{invoice_id:f.state.invoices[0].id,amount_twd:890}]}},'owner',env);assert.equal((await operationsMirrorStatus(env)).pending,2);await drainOperationsMirror(env,{transport:async(url,opt)=>{const v=JSON.parse(JSON.parse(opt.body).body);if(v.destination==='sheets')return new Response(JSON.stringify({ok:false,conflict:true,error_code:'MANUAL_EDIT'}));return ack(url,opt)}});const status=await operationsMirrorStatus(env);assert.equal(status.conflict,1);assert.equal(status.delivered,1);assert.equal((await drainOperationsMirror(env,{transport:ack})).handled,0);assert.equal((await loadOperations(env)).state.receipts.length,1);env.db.close()});
test('explicit Notion revision recheck resends a conflicted record even if the prior hash was delivered',async()=>{
 const{drainOperationsMirror,operationsMirrorStatus}=await import('../operations-mirror.js');
 const env=dbEnv();Object.assign(env,{PL3_OPS_SYNC_ENABLED:'true',PL3_FORMAL_SYNC_SECRET:'test',PL3_FORMAL_SHEETS_WEBHOOK_URL:'https://script.google.com/macros/s/test/exec'});
 await installOperations(env);env.db.prepare("UPDATE pl_ops_state SET document_json=? WHERE id='main'").run(JSON.stringify(fixture().state));
 let sent=0;const ack=async(u,opt)=>{sent++;const v=JSON.parse(JSON.parse(opt.body).body);return new Response(JSON.stringify({ok:true,ack_event_id:v.event_id,destination:v.destination,remote_id:v.record_id,remote_revision:'r2'}))};
 assert.equal((await drainOperationsMirror(env,{transport:ack})).handled,2);
 env.db.prepare("UPDATE pl_ops_sync_deliveries SET status='conflict',error_code='OPS_NOTION_REVISION_CHANGED' WHERE destination='notion'").run();
 assert.equal((await drainOperationsMirror(env,{transport:ack})).handled,0);
 assert.equal(env.db.prepare("UPDATE pl_ops_sync_deliveries SET status='pending',error_code=NULL,next_retry_at=NULL WHERE status='conflict' AND destination='notion' AND error_code='OPS_NOTION_REVISION_CHANGED'").run().changes,1);
 const retried=await drainOperationsMirror(env,{transport:ack});assert.equal(retried.handled,1);
 assert.equal(retried.results[0].destination,'notion');assert.equal(retried.results[0].status,'delivered');
 assert.equal(sent,3);assert.equal((await operationsMirrorStatus(env)).conflict,0);
 env.db.close();
});

test('forwarding records actual warehouse receipt without fabricating a purchase and never creates purchase demand',()=>{const f=fixture();let s=structuredClone(f.state);s.orders[0].service_kind='forwarding';s.orders[0].items[0].fulfillment_kind='forwarding';s=applyOperation(s,{type:'close_group',group_id:f.g},{id:'f-close',now:NOW}).state;const bill=s.invoices[0];s=applyOperation(s,{type:'receipt_confirm',customer_email:'customer@example.com',amount_twd:890,kind:'bank_confirmed',transaction_id:'forward-bank',evidence:'verified',confirmed:true,allocations:[{invoice_id:bill.id,amount_twd:890}]},{id:'f-paid',now:NOW}).state;assert.equal(operationalTasks(s).filter(t=>t.title==='可採購').length,0);assert.ok(operationalTasks(s).some(t=>t.title==='轉運品等待海外倉入庫'));const items=[{order_id:f.o,item_id:s.orders[0].items[0].id,quantity:2}];assert.throws(()=>applyOperation(s,{type:'purchase_record',shop:'official',official_order:'X',evidence:'proof',currency:'JPY',original_amount:0,actual_twd:0,items},{id:'f-purchase',now:NOW}),/轉運品/);for(const stage of ['overseas','transit','taiwan'])s=applyOperation(s,{type:'movement_record',stage,evidence:'actual shipment '+stage,items},{id:'f-'+stage,now:NOW}).state;assert.equal(s.orders[0].items[0].purchased,0);assert.equal(s.orders[0].items[0].taiwan,2);assert.equal(s.purchases.length,0);assert.equal(operationalTasks(s).filter(t=>t.title==='可採購').length,0);assert.throws(()=>applyOperation(s,{type:'order_cancel',order_id:f.o,reason:'cancel',confirmed:true},{id:'f-cancel',now:NOW}),/到倉/)});
test('backup preserves destination identities for deduplicated post-restore synchronization',async()=>{const{exportOperationsBackup,restoreOperationsBackup}=await import('../operations-backup.js');const source=dbEnv(),target=dbEnv();await installOperations(source);await installOperations(target);source.db.prepare("INSERT INTO pl_ops_sync_deliveries(record_id,destination,projection_hash,status,remote_id,remote_revision,lease_until) VALUES('O','notion','hash','processing','page-id','r1','future')").run();const backup=await exportOperationsBackup(source);await restoreOperationsBackup(backup,'owner',target,{confirmed:true,expected_version:0});const row=target.db.prepare('SELECT * FROM pl_ops_sync_deliveries').get();assert.equal(row.remote_id,'page-id');assert.equal(row.remote_revision,'r1');assert.equal(row.status,'retry');assert.equal(row.lease_until,null);source.db.close();target.db.close()});
test('destination authorization failures stop retries without blocking an independently acknowledged destination',async()=>{const{drainOperationsMirror,operationsMirrorStatus}=await import('../operations-mirror.js');const env=dbEnv();Object.assign(env,{PL3_OPS_SYNC_ENABLED:'true',PL3_FORMAL_SYNC_SECRET:'test',PL3_FORMAL_SHEETS_WEBHOOK_URL:'https://script.google.com/macros/s/test/exec'});await installOperations(env);env.db.prepare("UPDATE pl_ops_state SET document_json=? WHERE id='main'").run(JSON.stringify(fixture().state));let sent=0;const transport=async(u,opt)=>{sent++;const v=JSON.parse(JSON.parse(opt.body).body);return new Response(JSON.stringify(v.destination==='notion'?{ok:false,error_code:'OPS_NOTION_ACCESS_DENIED'}:{ok:true,ack_event_id:v.event_id,destination:v.destination,remote_id:v.record_id,remote_revision:'r1'}))};await drainOperationsMirror(env,{transport});const status=await operationsMirrorStatus(env);assert.equal(status.delivered,1);assert.equal(status.blocked,1);assert.equal(status.pending,0);assert.equal(status.failures[0].error_code,'OPS_NOTION_ACCESS_DENIED');assert.equal((await drainOperationsMirror(env,{transport})).handled,0);assert.equal(sent,2);env.db.close()});

test('owner mail acceptance prepares only a reviewable self-addressed draft with no financial or delivery side effect',()=>{const s=newOperations();const r=applyOperation(s,{type:'owner_test_notice'},{id:'OWNER-TEST',now:NOW});const n=r.state.notices[0];assert.equal(n.to,'petitelueur.pl@gmail.com');assert.equal(n.status,'draft');assert.equal(r.state.orders.length,0);assert.equal(r.state.invoices.length,0);assert.deepEqual(n.order_ids,[]);assert.equal(r.result.queue,undefined);assert.throws(()=>applyOperation(r.state,{type:'owner_test_notice'},{id:'DUP',now:NOW}),/已有/);assert.throws(()=>applyOperation(r.state,{type:'notice_approve',notice_id:n.id,version:1,confirmed:true,content:'not reviewed'},{id:'BAD',now:NOW}),/完整/)});

test('editing imported shipping settings never upgrades a source code to a verified manufacturer SKU',()=>{const f=fixture();const s=structuredClone(f.state);s.products=[{id:'imported',group_id:f.g,name:'badge box',sku:'NEOGDS-SOURCE',sku_confirmed:false,shipping_units_confirmed:false,shipping_units:1,price_twd:780,published:false,status:'available',source_url:'https://www.neowing.co.jp/product/source'}];const c={type:'product_save',...s.products[0],shipping_units:6,shipping_units_confirmed:true,published:true,confirmed:true,setting_evidence:'6 badges × existing 1 unit badge policy'};const r=applyOperation(s,c,{id:'edit',now:NOW}).state.products[0];assert.equal(r.sku_confirmed,false);assert.equal(r.shipping_units_confirmed,true);assert.equal(r.shipping_units,6);assert.equal(r.setting_evidence,c.setting_evidence);const verified=applyOperation({...s,products:[{...s.products[0],sku_confirmed:true}]},{...c,sku_confirmed:undefined},{id:'retain',now:NOW}).state.products[0];assert.equal(verified.sku_confirmed,true);const changed=applyOperation({...s,products:[{...s.products[0],sku_confirmed:true}]},{...c,sku:'OTHER',sku_confirmed:false},{id:'changed',now:NOW}).state.products[0];assert.equal(changed.sku_confirmed,false);});

test('pending international shipping accepts applications only, without default shares, invoices or customer payment prompts',async()=>{
 const {checkoutOperations,publicOperationsCatalog}=await import('../operations-store.js');
 const env=dbEnv();await installOperations(env);
 const group='NEOWING-KIMISHINU-FIG-261028';
 let s=newOperations();s=applyOperation(s,{type:'group_save',id:group,title:'席娜＆美美 1/8 模型',status:'open',deadline:'2099-01-01T00:00:00Z',payment_due_at:'2099-01-03T00:00:00Z'},{id:'group',now:NOW}).state;
 const item={type:'product_save',group_id:group,name:'席娜＆美美 1/8 模型',sku:'NEOGDS-1098444',price_twd:7590,shipping_units:null,shipping_units_confirmed:false,manual_review_required:true,source_url:'https://www.neowing.co.jp/product/NEOGDS-1098444',published:true,confirmed:true};
 assert.throws(()=>applyOperation(s,{...item,manual_review_required:false},{id:'unsafe',now:NOW}),/人工審核/);
 s=applyOperation(s,item,{id:'product',now:NOW}).state;
 assert.equal(s.products[0].shipping_units,null);
 assert.equal(publicOperationsCatalog(s).products[0].shipping_pending,true);
 env.db.prepare("UPDATE pl_ops_state SET document_json=? WHERE id='main'").run(JSON.stringify(s));
 const body={key:'shipping-review-test-00001',group_id:group,name:'測試申請者',adult_confirmed:true,terms_confirmed:true,items:[{product_id:s.products[0].id,quantity:1}]};
 const result=await checkoutOperations(body,'applicant@example.com',env);
 let current=await loadOperations(env),o=current.state.orders.find(x=>x.id===result.result.order_id);
 assert.equal(result.result.status,'review_pending');assert.equal(o.items[0].shipping_units,null);assert.equal(o.items[0].shipping_units_confirmed,false);
 assert.equal(current.state.invoices.length,0);assert.equal(current.state.notices.length,0);
 assert.ok(operationalTasks(current.state).some(t=>t.title==='待實算申請需主購人工審核'));
 assert.throws(()=>applyOperation(current.state,{type:'payment_report',order_id:o.id,authenticated_email:o.email,amount_twd:7590,method:'銀行匯款'},{id:'no-payment'}),/禁止/);
 assert.throws(()=>applyOperation(current.state,{type:'order_review',order_id:o.id,confirmed:true,evidence:''},{id:'no-evidence'}),/依據/);
 await executeOperation({key:'shipping-close-00001',version:current.version,command:{type:'close_group',group_id:group}},'owner',env);
 current=await loadOperations(env);assert.equal(current.state.invoices.length,0);assert.equal(current.state.notices.length,0);
 await executeOperation({key:'shipping-review-0001',version:current.version,command:{type:'order_review',order_id:o.id,confirmed:true,evidence:'已核對商品款，國際運費實際分攤於二補確認'}},'owner',env);
 current=await loadOperations(env);assert.equal(current.state.invoices.length,0);
 await executeOperation({key:'shipping-reclose-01',version:current.version,command:{type:'close_group',group_id:group}},'owner',env);
 current=await loadOperations(env);assert.equal(current.state.invoices.length,1);assert.equal(current.state.notices.length,1);assert.equal(current.state.notices[0].status,'draft');
 env.db.close();
});
